    private readonly List<ItaDrawBatch> itaBatches=new(),itaSelectedBatches=new();private int selectedItaOrder=-1;
    private ItaEntry? draggingIta;private ItaState itaDragStart;private Point itaDragMouse;private System.Numerics.Vector3 itaDragWorld;private int itaDragAxis;
