    private void UploadIta()
    {
        itaGpuDirty=false;itaCount=itaSelectedCount=itaModelCount=itaSelectedModelCount=0;if(!glReady||itaScene==null)return;EnsureItaBuffers();
        var normal=new List<float>();var selected=new List<float>();var gizmos=new[]{new List<float>(),new List<float>(),new List<float>()};
        var models=new Dictionary<ItaTextureKey,List<float>>();var selectedModels=new Dictionary<ItaTextureKey,List<float>>();
        foreach(ItaEntry entry in itaScene.Entries)
        {
            bool isSelected=entry.FileOrder==selectedItaOrder;AddItaMarker(isSelected?selected:normal,entry,isSelected);if(isSelected&&entry.AppearanceType==0)AddItaGizmo(gizmos,entry);
            if(itmCatalog?.ModelParts.TryGetValue(entry.ItemId,out IReadOnlyList<EtmModelPart>? parts)==true)
                foreach(EtmModelPart part in parts)foreach(var material in part.Triangles.GroupBy(t=>t.TextureIndex))
                {var key=new ItaTextureKey(part.TextureFallback?.FileOrder??-1,material.Key);var buckets=isSelected?selectedModels:models;if(!buckets.TryGetValue(key,out List<float>? values)){values=new();buckets[key]=values;}AddItaModel(values,entry,material);}
        }
        UploadLineBuffer(itaVao,itaVbo,normal,out itaCount);UploadLineBuffer(itaSelectedVao,itaSelectedVbo,selected,out itaSelectedCount);
        for(int i=0;i<3;i++)UploadLineBuffer(itaGizmoVaos[i],itaGizmoVbos[i],gizmos[i],out itaGizmoCounts[i]);
        UploadEnemyModelBuffer(itaModelVao,itaModelVbo,BuildItaBatches(models,itaBatches),out itaModelCount);UploadEnemyModelBuffer(itaSelectedModelVao,itaSelectedModelVbo,BuildItaBatches(selectedModels,itaSelectedBatches),out itaSelectedModelCount);
    }
    private void EnsureItaBuffers(){if(itaVao==0)itaVao=GL.GenVertexArray();if(itaVbo==0)itaVbo=GL.GenBuffer();if(itaSelectedVao==0)itaSelectedVao=GL.GenVertexArray();if(itaSelectedVbo==0)itaSelectedVbo=GL.GenBuffer();if(itaModelVao==0)itaModelVao=GL.GenVertexArray();if(itaModelVbo==0)itaModelVbo=GL.GenBuffer();if(itaSelectedModelVao==0)itaSelectedModelVao=GL.GenVertexArray();if(itaSelectedModelVbo==0)itaSelectedModelVbo=GL.GenBuffer();for(int i=0;i<3;i++){if(itaGizmoVaos[i]==0)itaGizmoVaos[i]=GL.GenVertexArray();if(itaGizmoVbos[i]==0)itaGizmoVbos[i]=GL.GenBuffer();}}
    private void AddItaMarker(List<float> values,ItaEntry e,bool selected){var p=ItaWorld(e);float r=selected?1.8f:1.25f;void L(System.Numerics.Vector3 a,System.Numerics.Vector3 b)=>values.AddRange(new[]{a.X,a.Y,a.Z,0f,0f,0f,b.X,b.Y,b.Z,0f,0f,0f});L(p-new System.Numerics.Vector3(r,0,0),p+new System.Numerics.Vector3(r,0,0));L(p-new System.Numerics.Vector3(0,r,0),p+new System.Numerics.Vector3(0,r,0));L(p-new System.Numerics.Vector3(0,0,r),p+new System.Numerics.Vector3(0,0,r));}
    private void AddItaGizmo(List<float>[] axes,ItaEntry e){var p=ItaWorld(e);void L(int a,System.Numerics.Vector3 x,System.Numerics.Vector3 y)=>axes[a].AddRange(new[]{x.X,x.Y,x.Z,0f,0f,0f,y.X,y.Y,y.Z,0f,0f,0f});if(ItaTransformMode==EtsGizmoMode.Move){for(int i=0;i<3;i++){var axis=i==0?System.Numerics.Vector3.UnitX:i==1?System.Numerics.Vector3.UnitY:System.Numerics.Vector3.UnitZ;L(i,p,p+axis*5f);}}else{for(int i=0;i<3;i++)for(int n=0;n<40;n++){float a=n*MathF.Tau/40,b=(n+1)*MathF.Tau/40;System.Numerics.Vector3 A=i==0?new(0,MathF.Cos(a)*3.8f,MathF.Sin(a)*3.8f):i==1?new(MathF.Cos(a)*3.8f,0,MathF.Sin(a)*3.8f):new(MathF.Cos(a)*3.8f,MathF.Sin(a)*3.8f,0);System.Numerics.Vector3 B=i==0?new(0,MathF.Cos(b)*3.8f,MathF.Sin(b)*3.8f):i==1?new(MathF.Cos(b)*3.8f,0,MathF.Sin(b)*3.8f):new(MathF.Cos(b)*3.8f,MathF.Sin(b)*3.8f,0);L(i,p+A,p+B);}}}
    private void AddItaModel(List<float> values,ItaEntry e,IEnumerable<ScenarioTriangle> triangles){foreach(var t in triangles){var a=TransformIta(t.A,e);var b=TransformIta(t.B,e);var c=TransformIta(t.C,e);var n=System.Numerics.Vector3.Cross(b-a,c-a);float l=n.Length();if(!float.IsFinite(l)||l<.000001f)continue;n/=l;WriteEnemyModelVertex(values,a,n,FlipAssetUv(t.UvA));WriteEnemyModelVertex(values,b,n,FlipAssetUv(t.UvB));WriteEnemyModelVertex(values,c,n,FlipAssetUv(t.UvC));}}
    private System.Numerics.Vector3 TransformIta(System.Numerics.Vector3 v,ItaEntry e){if(MathF.Abs(e.RotationX)>.000001f){float c=MathF.Cos(e.RotationX),s=MathF.Sin(e.RotationX);v=new(v.X,v.Y*c-v.Z*s,v.Y*s+v.Z*c);}if(MathF.Abs(e.RotationY)>.000001f){float c=MathF.Cos(e.RotationY),s=MathF.Sin(e.RotationY);v=new(v.X*c+v.Z*s,v.Y,-v.X*s+v.Z*c);}if(MathF.Abs(e.RotationZ)>.000001f){float c=MathF.Cos(e.RotationZ),s=MathF.Sin(e.RotationZ);v=new(v.X*c-v.Y*s,v.X*s+v.Y*c,v.Z);}return v+ItaWorld(e);}
    private System.Numerics.Vector3 ItaWorld(ItaEntry e)
    {
        if(e.AppearanceType==2&&etsScene?.Entries.FirstOrDefault(x=>x.InstanceIndex==e.LinkedInstanceId) is EtsEntry obj)return EtsWorld(obj);
        if(e.AppearanceType==1&&eslScene?.Entries.FirstOrDefault(x=>x.Index==e.LinkedInstanceId) is EslEnemyEntry enemy)return EslToWorld(enemy);
        return e.Position*ItaWorldScale;
    }
    private static List<float> BuildItaBatches(Dictionary<ItaTextureKey,List<float>> buckets,List<ItaDrawBatch> batches){batches.Clear();var all=new List<float>();foreach(var p in buckets){int first=all.Count/8;all.AddRange(p.Value);if(p.Value.Count>0)batches.Add(new(p.Key,first,p.Value.Count/8));}return all;}
    private void DrawItaGpu(){GL.Enable(EnableCap.DepthTest);GL.Disable(EnableCap.CullFace);GL.Uniform1(uUnlit,0);DrawItaModels(itaModelVao,itaModelCount,itaBatches);DrawItaModels(itaSelectedModelVao,itaSelectedModelCount,itaSelectedBatches);GL.Uniform1(uUseTexture,0);GL.Uniform1(uUnlit,1);GL.Disable(EnableCap.DepthTest);GL.Uniform3(uColor,.95f,.35f,.75f);GL.BindVertexArray(itaVao);GL.LineWidth(3);GL.DrawArrays(PrimitiveType.Lines,0,itaCount);if(assetMeshSelection==null){GL.Uniform3(uColor,1f,.85f,.12f);GL.BindVertexArray(itaSelectedVao);GL.LineWidth(5);GL.DrawArrays(PrimitiveType.Lines,0,itaSelectedCount);var colors=new[]{(1f,.16f,.12f),(.2f,.9f,.25f),(.15f,.48f,1f)};for(int i=0;i<3;i++){GL.Uniform3(uColor,colors[i].Item1,colors[i].Item2,colors[i].Item3);GL.BindVertexArray(itaGizmoVaos[i]);GL.DrawArrays(PrimitiveType.Lines,0,itaGizmoCounts[i]);}}GL.LineWidth(1);GL.Enable(EnableCap.DepthTest);GL.Enable(EnableCap.CullFace);}
    private void DrawItaModels(int vao,int count,List<ItaDrawBatch> batches){if(count==0)return;GL.BindVertexArray(vao);GL.Uniform3(uColor,.85f,.85f,.85f);foreach(var b in batches){if(glItaTextures.TryGetValue(b.Key,out int texture)){GL.Uniform1(uUseTexture,1);GL.BindTexture(TextureTarget.Texture2D,texture);}else GL.Uniform1(uUseTexture,0);GL.DrawArrays(PrimitiveType.Triangles,b.First,b.Count);}GL.BindTexture(TextureTarget.Texture2D,0);}
    private void UploadItaTextures(){itaTexturesDirty=false;foreach(int t in glItaTextures.Values)if(t!=0)GL.DeleteTexture(t);glItaTextures.Clear();glItaTransparency.Clear();if(itmCatalog==null)return;var reader=new Core.Textures.TplReader();var decoder=new Core.Textures.TextureDecoder();foreach(var parts in itmCatalog.ModelParts.Values)foreach(var part in parts){if(part.TextureFallback==null)continue;foreach(int index in part.Triangles.Select(x=>x.TextureIndex).Distinct())try{using var ms=new MemoryStream(part.TextureFallback.Data,false);using var br=new BinaryReader(ms);var tpl=reader.ReadTexture(br,index);ms.Position=0;using var bitmap=decoder.Decode(tpl,br);var key=new ItaTextureKey(part.TextureFallback.FileOrder,index);glItaTextures[key]=CreateEtsGlTexture(bitmap);glItaTransparency[key]=BitmapHasTransparency(bitmap);}catch{}}}
    private ItaEntry? PickIta(Point mouse){ItaEntry? hit=null;float best=float.PositiveInfinity;if(itaScene==null)return null;foreach(var e in itaScene.Entries){if(itmCatalog?.ModelParts.TryGetValue(e.ItemId,out var parts)==true)foreach(var part in parts)foreach(var triangle in part.Triangles){var a=TransformIta(triangle.A,e);var b=TransformIta(triangle.B,e);var c=TransformIta(triangle.C,e);if(!TryProjectWorldToScreen(a,out PointF pa)||!TryProjectWorldToScreen(b,out PointF pb)||!TryProjectWorldToScreen(c,out PointF pc)||!PointInScreenTriangle(mouse,pa,pb,pc))continue;float depth=System.Numerics.Vector3.DistanceSquared(cameraPosition,(a+b+c)/3f);if(depth<best){best=depth;hit=e;}}if(!TryProjectWorldToScreen(ItaWorld(e),out PointF p))continue;float d=(p.X-mouse.X)*(p.X-mouse.X)+(p.Y-mouse.Y)*(p.Y-mouse.Y);if(d<24*24&&d<best){best=d;hit=e;}}return hit;}
    private AssetMeshSelection? PickItaSurface(Point mouse,ItaEntry e){if(itmCatalog?.ModelParts.TryGetValue(e.ItemId,out var parts)!=true)return null;AssetMeshSelection? hit=null;float best=float.PositiveInfinity;for(int pi=0;pi<parts.Count;pi++)for(int ti=0;ti<parts[pi].Triangles.Count;ti++){var t=parts[pi].Triangles[ti];var p=new[]{TransformIta(t.A,e),TransformIta(t.B,e),TransformIta(t.C,e)};if(!TryProjectWorldToScreen(p[0],out PointF a)||!TryProjectWorldToScreen(p[1],out PointF b)||!TryProjectWorldToScreen(p[2],out PointF c)||!PointInScreenTriangle(mouse,a,b,c))continue;float depth=System.Numerics.Vector3.DistanceSquared(cameraPosition,(p[0]+p[1]+p[2])/3);if(depth>=best)continue;best=depth;int element=0;var position=(p[0]+p[1]+p[2])/3;if(AssetSelectionMode==AssetMeshSelectionMode.Vertex){var q=new[]{a,b,c};element=Enumerable.Range(0,3).OrderBy(i=>(q[i].X-mouse.X)*(q[i].X-mouse.X)+(q[i].Y-mouse.Y)*(q[i].Y-mouse.Y)).First();position=p[element];}else if(AssetSelectionMode==AssetMeshSelectionMode.Edge){var q=new[]{a,b,c};element=Enumerable.Range(0,3).OrderBy(i=>DistancePointToSegment(mouse,q[i],q[(i+1)%3])).First();position=(p[element]+p[(element+1)%3])/2;}hit=new(AssetSelectionMode,pi,ti,element,position);}return hit;}
    private int PickItaAxis(Point mouse,ItaEntry e){var p=ItaWorld(e);if(!TryProjectWorldToScreen(p,out PointF a))return 0;float best=11;int result=0;var ends=new[]{p+System.Numerics.Vector3.UnitX*5,p+System.Numerics.Vector3.UnitY*5,p+System.Numerics.Vector3.UnitZ*5};for(int i=0;i<3;i++)if(TryProjectWorldToScreen(ends[i],out PointF b)){float d=DistancePointToSegment(mouse,a,b);if(d<best){best=d;result=i+1;}}return result;}
    private bool TryBeginItaDrag(Point mouse){if(assetMeshSelection!=null||AssetMeshEditingEnabled&&AssetSelectionMode==AssetMeshSelectionMode.Object)return false;ItaEntry? e=itaScene?.Entries.FirstOrDefault(x=>x.FileOrder==selectedItaOrder);if(e==null||e.AppearanceType!=0)return false;int axis=PickItaAxis(mouse,e);if(axis==0&&!ReferenceEquals(PickIta(mouse),e))return false;draggingIta=e;itaDragStart=ItaState.From(e);itaDragMouse=mouse;itaDragWorld=ItaWorld(e);itaDragAxis=axis==0?(ItaTransformMode==EtsGizmoMode.Move?7:2):axis;return true;}
    private void UpdateItaDrag(Point mouse){if(draggingIta==null)return;int dx=mouse.X-itaDragMouse.X,dy=mouse.Y-itaDragMouse.Y;if(ItaTransformMode==EtsGizmoMode.Move){if(itaDragAxis is 1 or 3 or 7&&TryScreenPointOnHorizontalPlane(itaDragMouse,itaDragWorld.Y,out var a)&&TryScreenPointOnHorizontalPlane(mouse,itaDragWorld.Y,out var b)){var d=(b-a)/ItaWorldScale;if(itaDragAxis is 1 or 7)draggingIta.PositionX=itaDragStart.Px+d.X;if(itaDragAxis is 3 or 7)draggingIta.PositionZ=itaDragStart.Pz+d.Z;}else if(itaDragAxis==2)draggingIta.PositionY=itaDragStart.Py-dy*25;}else{float d=dx*MathF.PI/360;if(itaDragAxis==1)draggingIta.RotationX=itaDragStart.Rx+d;else if(itaDragAxis==3)draggingIta.RotationZ=itaDragStart.Rz+d;else draggingIta.RotationY=itaDragStart.Ry+d;}itaGpuDirty=true;ItaEntryEdited?.Invoke(draggingIta);Invalidate();}
    private void EndItaDrag(){if(draggingIta!=null)ItaEntryEdited?.Invoke(draggingIta);draggingIta=null;itaDragAxis=0;}
    private readonly record struct ItaState(float Px,float Py,float Pz,float Rx,float Ry,float Rz){public static ItaState From(ItaEntry e)=>new(e.PositionX,e.PositionY,e.PositionZ,e.RotationX,e.RotationY,e.RotationZ);}
